package com.vr3th.mediacompressor.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.vr3th.mediacompressor.data.ProcessResult;import com.vr3th.mediacompressor.ui.theme.*;import com.vr3th.mediacompressor.utils.FormatUtils
@Composable fun ResultScreen(result:ProcessResult,onShare:()->Unit,onDone:()->Unit){Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.SpaceBetween){Column{Text(if(result.isSuccess)"Compression Finished" else "Process Failed",style=MaterialTheme.typography.titleLarge);Spacer(Modifier.height(20.dp));if(result.isSuccess){Text("Original Size: ${FormatUtils.formatFileSize(result.originalSize)}");Text("Compressed Size: ${FormatUtils.formatFileSize(result.compressedSize)}");Text("Saved: ${FormatUtils.calculateReduction(result.originalSize,result.compressedSize)}");Text("Resolution: ${result.originalRes} → ${result.outputRes}");Text("Codec Strategy: ${result.outputCodec}");Text("Process Time: ${result.processingTimeMs} ms")}else Text(result.errorMessage?:"Unknown error occurred.",color=ErrorRed)};Column{if(result.isSuccess)Button(onClick=onShare,Modifier.fillMaxWidth()){Icon(Icons.Default.Share,null);Spacer(Modifier.width(8.dp));Text("Share File")};OutlinedButton(onClick=onDone,Modifier.fillMaxWidth()){Text("Back to Home")}}}}
